from fastapi import APIRouter, Depends, HTTPException, Request, Response
from fastapi.routing import APIRoute
from typing import Callable

class ResilientRoute(APIRoute):
    def get_route_handler(self) -> Callable:
        original_route_handler = super().get_route_handler()
        async def custom_handler(request: Request) -> Response:
            # Authorization exceptions must never be caught and converted to permissive fallbacks
            return await original_route_handler(request)
        return custom_handler

router = APIRouter(route_class=ResilientRoute, prefix="/customer-portal")

@router.get("/accounts/{account_id}/profile", dependencies=[Depends(enforce_strict_customer_ownership)])
async def get_account_profile(account_id: str, current_user: User = Depends(get_optional_user)):
    profile = await AccountManager.fetch_profile(account_id=account_id)
    return {"account_id": account_id, "profile": profile.details}
